import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';
import { 
  ChevronLeft, Calendar, User, MapPin, Clock, 
  MoreVertical, Search, Layers, ChevronDown, Plus, Minus 
} from 'lucide-react';
import './MeetingRoom.css';

const MeetingRoom = () => {
  const navigate = useNavigate();
  // view 状态：'list' (列表), 'filter' (过滤表单), 'results' (搜索结果)
  const [view, setView] = useState('list');
  const [attendees, setAttendees] = useState(0);

  // 处理返回逻辑：逐级回退
  const handleBack = () => {
    if (view === 'results') setView('filter');
    else if (view === 'filter') setView('list');
    else navigate('/');
  };

  // 时间限制：今天到5年后
  const today = new Date().toISOString().split('T')[0];
  const maxDate = new Date();
  maxDate.setFullYear(maxDate.getFullYear() + 5);
  const maxDateStr = maxDate.toISOString().split('T')[0];

  return (
    <div className="meeting-room-container">
      {/* 1. 顶部导航栏 - 搜索模式下标题为 Searching */}
      <nav className="top-nav-bar">
        <div className="back-arrow-wrapper" onClick={handleBack}>
          <ChevronLeft size={24} color="#ffffff" strokeWidth={2.5} />
        </div>
        <span className="nav-title">{view === 'list' ? "Meeting Room" : "Searching"}</span>
      </nav>

      {/* 2. 独立滚动区域 */}
      <div className="scrollable-area">
        {view === 'list' && (
          /* --- 视图 A：原有会议列表 --- */
          <div className="content-padding">
            <div className="tabs-header">
              <button className="tab active">List All</button>
              <button className="tab">Today</button>
              <button className="tab">Week</button>
            </div>
            <div className="summary-banner">
              <div className="summary-icon"><Calendar size={22} color="#1976d2" strokeWidth={2} /></div>
              <div className="summary-info">
                <h2 style={{ fontSize: "13pt", fontWeight: "bold", margin: 0 }}>1 Meeting Upcoming</h2>
                <p style={{ fontSize: "10pt", fontWeight: "bold", margin: "2px 0 0", color: "#000000" }}>22 Jan, Thursday</p>
              </div>
            </div>
            <div className="meeting-list">
              <div className="details-card">
                <div className="card-top">
                  <h3 style={{margin: 0, fontSize: '15px'}}>UAT Briefing</h3>
                  <button className="more-options"><MoreVertical size={20} color="#999" /></button>
                </div>
                <div className="info-rows">
                  <div className="row"><span className="icon"><User size={18} /></span><span className="text">ALAN TAN WAI LOON</span></div>
                  <div className="row"><span className="icon"><MapPin size={18} /></span><span className="text">Idea Lab 6</span></div>
                  <div className="row"><span className="icon"><Calendar size={18} /></span><span className="text">2026-01-22</span></div>
                  <div className="row"><span className="icon"><Clock size={18} /></span><span className="text">12:00 PM - 12:30 PM</span></div>
                </div>
                <div className="card-bottom">
                  <div className="attendee-count">
                    <div className="icon-circle"><User size={14} strokeWidth={2.5} /></div>
                    <span className="attendee-number">1</span>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}

        {view === 'filter' && (
          /* --- 视图 B：搜索过滤表单 (Searching 子页面) --- */
          <div className="filter-form-container">
            <p className="filter-subtitle">Find A Meeting Room</p>
            <div className="form-group">
              <label>Date</label>
              <div className="form-field"><input type="date" defaultValue={today} min={today} max={maxDateStr} /><Calendar size={18} color="#666" /></div>
            </div>
            <div className="form-group">
              <label>I need a meeting room from</label>
              <div className="form-field select"><span>Please Select Time</span><ChevronDown size={18} color="#666" /></div>
            </div>
            <div className="form-group">
              <label>I need a meeting room for</label>
              <div className="form-field select"><span>Please Select Time</span><ChevronDown size={18} color="#666" /></div>
            </div>
            <div className="form-group">
              <label>Appointment Type</label>
              <div className="form-field select"><span>Please select appointment type</span><ChevronDown size={18} color="#666" /></div>
            </div>
            <div className="form-group">
              <label>Floor</label>
              <div className="form-field select"><span>Please select a Floor</span><ChevronDown size={18} color="#666" /></div>
            </div>
            <div className="features-section">
              <label>Room Features</label>
              {["Projector", "Interactive TV", "Non-Interactive TV", "180° Camera", "Conference Camera", "Tabletop Teams Panel", "Wireless Mic"].map(item => (
                <div className="feature-row" key={item}><span>{item}</span><input type="checkbox" /></div>
              ))}
            </div>
            <div className="attendee-counter-row">
              <label>Number of Attendees</label>
              <div className="counter-controls">
                <button onClick={() => setAttendees(Math.max(0, attendees - 1))}><Minus size={18} /></button>
                <span>{attendees}</span>
                <button onClick={() => setAttendees(attendees + 1)}><Plus size={18} /></button>
              </div>
            </div>
            <button className="form-search-btn-capsule" onClick={() => setView('results')}>Search Room</button>
          </div>
        )}

        {view === 'results' && (
          /* --- 视图 C：搜索结果 (Searching 结果页) --- */
          <div className="search-view-container">
            {/* 顶部的搜索触发按钮 (外观像输入框，点击回表单) */}
            <button className="search-trigger-as-input" onClick={() => setView('filter')}>
              <span className="placeholder">Search room name...</span>
              <Search size={20} color="#999" />
            </button>
            <div className="search-results-list">
              {[...Array(10)].map((_, index) => (
                <div key={index} className="room-sub-box">
                  <div className="room-box-left"></div>
                  <div className="room-box-right">
                    <h4 className="room-title">Idea Lab {index + 1}</h4>
                    <div className="room-details">
                      <div className="detail-item"><User size={14} color="#666" /> <span>8 seats</span></div>
                      <div className="detail-item"><Layers size={14} color="#666" /> <span>Level 19</span></div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      {/* 3. 底部 Search Room 按钮 (仅在列表视图显示) */}
      {view === 'list' && (
        <div className="search-footer">
          <button className="search-room-btn" onClick={() => setView('filter')}>
            <Search size={18} style={{marginRight: '8px'}} />
            Search Room
          </button>
        </div>
      )}
    </div>
  );
};

export default MeetingRoom;
